service.method:

UPDATE SFILE
   SET DEL_FLAG = 'Y'
	  ,CHANGE_DATE = ${current.date}
	  ,CHANGE_TIME = ${current.time}
 WHERE 1=1 
   AND DOC_NO  = ${attach_key}
   AND DOC_SEQ = ${attach_seq}


SELECT DES_FILE_NAME
      ,SRC_FILE_NAME
      ,TYPE
  FROM SFILE
 WHERE DOC_NO  = ${attach_key}
   AND DOC_SEQ = ${attach_seq}
